ability_code.before:
// Thousand Refractions: [Class Bonus] On Hit: If prepared, wake up champion and return CARDNAME to hand.
if(!IsClassBonusActive($player)) return;
$intentCards = GetIntentCards($player);
foreach($intentCards as $iMZ) {
    $iObj = GetZoneObject($iMZ);
    if($iObj !== null && $iObj->CardID === "XLbCBxla8K" && in_array("PREPARED", $iObj->TurnEffects)) {
        // Wake up the champion
        $myField = GetZone("myField");
        foreach($myField as $fi => $fieldObj) {
            if(PropertyContains(CardType($fieldObj->CardID), "CHAMPION")) {
                WakeupCard($player, "myField-" . $fi);
                break;
            }
        }
        // Return Thousand Refractions from intent to hand
        MZMove($player, $iMZ, "myHand");
        break;
    }
}

